$text = Get-Content app\src\main\java\com\example\connectany\presentation\device\DeviceConfigScreen.kt -Raw; $lines = $text -split \"\r?\n\"; $p = 0; $b = 0; for ($i=0; $i -lt $lines.Length; $i++) { $line = $lines[$i]; $p += ($line.ToCharArray() | Where-Object { $_ -eq \"(\" }).Count; $p -= ($line.ToCharArray() | Where-Object { $_ -eq \")\" }).Count; $b += ($line.ToCharArray() | Where-Object { $_ -eq \"{\" }).Count; $b -= ($line.ToCharArray() | Where-Object { $_ -eq \"}\" }).Count; Write-Output (\"{0,3} | P: {1,2} | B: {2,2} | {3}\" -f ($i+1), $p, $b, $line) }
